{
  "Q1": {
    "q1a_rule": {
      "verdict": "yes",
      "rationale": "Identifies FR Doc. 2026-15665, 91 FR 49178-49227, published August 3, 2026, effective September 2, 2026, docket OPM-2025-0107, RIN 3206-AO86."
    },
    "q1b_nprm": {
      "verdict": "yes",
      "rationale": "Identifies the proposed rule as FR Doc. 2026-04377, 91 FR 10904-10934, published March 5, 2026."
    },
    "q1c_first": {
      "verdict": "yes",
      "rationale": "Lists FR Doc. 2026-17335, published August 25, 2026, effective September 2, 2026, and describes correction of typographical and clerical errors in amendatory instructions and regulatory text."
    },
    "q1c_second": {
      "verdict": "yes",
      "rationale": "Lists FR Doc. 2026-18800, published and effective September 15, 2026, and says it restores 5 CFR 330.602(1)(i)-(ii), the CTAP definition of 'displaced', after instruction 11 inadvertently removed them."
    },
    "q1d_applicability": {
      "verdict": "yes",
      "rationale": "Correctly makes the notice-issuance date the test: before September 2, 2026 means the earlier rules; on or after means the amended rules. It cites the DATES paragraph at 91 FR 49178 and the implementation discussion at 91 FR 49206-49207."
    },
    "q1e_appeals": {
      "verdict": "yes",
      "rationale": "Lists 2026-15666, effective September 2, 2026 and in force, replacing subpart I and revising 351.802(a)(6) and 351.807(e)."
    },
    "q1e_leave": {
      "verdict": "yes",
      "rationale": "Lists 2026-21320, says it revises 351.806, gives November 18, 2026 as the effective date, and says it is not in force today."
    },
    "q1e_senior": {
      "verdict": "yes",
      "rationale": "Lists 2026-21316, says it revises 351.203 and 351.503, gives November 18, 2026 as the effective date, and says it is not in force today."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "The factual claims are consistently tied to FR document numbers, CFR paragraphs, or FR pages."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation. The extra reference to 2026-13715 amending 351.504 is confirmed by that rule's amendatory text at 91 FR 41537."
    }
  },
  "Q2": {
    "q2a_abbott": {
      "verdict": "yes",
      "rationale": "Abbott: 7 + 5 + 5 = 17, no veterans' points, total 17."
    },
    "q2a_bianchi": {
      "verdict": "yes",
      "rationale": "Bianchi: 5 + 0 + 3 = 8, plus 5 for a 30-percent-or-more compensable disability, total 13."
    },
    "q2a_castillo": {
      "verdict": "yes",
      "rationale": "Castillo: performance credit 17 and 0 veterans' points, total 17; correctly applies 351.504(b) to deny preference to a 20-year length-of-service retiree with no qualifying disability retirement."
    },
    "q2a_dalton": {
      "verdict": "yes",
      "rationale": "Dalton: two ratings, 7 + 0, proxy 3.5, performance credit 10.5, plus 3, total 13.5."
    },
    "q2a_eze": {
      "verdict": "yes",
      "rationale": "Eze: 5 + 5 + 5 = 15, no veterans' points, total 15, and correctly placed in tenure subgroup II."
    },
    "q2a_fontaine": {
      "verdict": "yes",
      "rationale": "Fontaine: one rating, 5 x 3 = 15, total 15."
    },
    "q2b_order": {
      "verdict": "yes",
      "rationale": "Gives the correct order Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi and explains both ties: Abbott ahead of Castillo by earlier SCD; Fontaine ahead of Eze because subgroup I outranks subgroup II."
    },
    "q2b_released": {
      "verdict": "yes",
      "rationale": "Says Bianchi and Dalton are released."
    },
    "q2c_old": {
      "verdict": "yes",
      "rationale": "Says Bianchi would have stood above Abbott under the earlier rules, citing the 2026 final rule's description at 91 FR 49198: tenure group, then veterans' preference subgroup AD/A/B, then service as augmented by performance credit."
    },
    "q2d_records": {
      "verdict": "yes",
      "rationale": "Under 351.506(b)-(c), allows inspection of the complete retention register, including other employees' names, augmented performance credit, and SCDs, plus registers for other relevant positions."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "The answer supplies CFR and FR citations throughout."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation."
    }
  },
  "Q3": {
    "q3a_case_a": {
      "verdict": "yes",
      "rationale": "A is not a preference eligible, gets 0 points, and is subgroup B; the answer rests this on 351.504(b)(2) failing because retired pay is based on 22 years."
    },
    "q3a_case_b": {
      "verdict": "yes",
      "rationale": "B is not a preference eligible, gets 0 points, and is subgroup B; the answer correctly applies 351.504(b)(4): a commander/major-or-above retiree who is a disabled veteran must also satisfy (b)(1), (2), or (3), which he does not."
    },
    "q3a_case_c": {
      "verdict": "yes",
      "rationale": "C is a preference eligible, gets +5, and is subgroup AD under 351.504(b)(1)(i) and (a)(1)."
    },
    "q3a_case_d": {
      "verdict": "yes",
      "rationale": "D is not a preference eligible, gets 0 points, and is subgroup B; retired pay is based on 24 years and no other condition applies."
    },
    "q3a_case_e": {
      "verdict": "yes",
      "rationale": "E is a preference eligible because retired pay is not based on 20 or more years (16 years), gets +3 because the disability is under 30 percent, and is subgroup A under 351.504(b)(2)."
    },
    "q3b_scd_a": {
      "verdict": "yes",
      "rationale": "Employee A is not a preference eligible, so only the 2 years of campaign service count: September 7, 2010 minus 2 years = September 7, 2008."
    },
    "q3b_scd_c": {
      "verdict": "yes",
      "rationale": "Employee C is a preference eligible, so all 14 years count: September 7, 2010 minus 14 years = September 7, 1996."
    },
    "q3c_labels": {
      "verdict": "yes",
      "rationale": "Says the AD/A/B subgroups are identifiers that determine the 5/3/0 points and are not themselves a ranking step or tie-breaker."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant CFR paragraphs and FR page."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation."
    }
  },
  "Q4": {
    "q4a_farah": {
      "verdict": "yes",
      "rationale": "Farah: all five ratings are within the four-year period; three most recent are 7, 3, 3 = 13."
    },
    "q4b_cutoff_date": {
      "verdict": "yes",
      "rationale": "Cutoff date: September 3, 2026 minus 45 days = July 20, 2026."
    },
    "q4b_credit": {
      "verdict": "yes",
      "rationale": "With the cutoff, the August 10, 2026 rating is excluded; 3 + 3 + 5 = 11."
    },
    "q4c_not_on_record": {
      "verdict": "yes",
      "rationale": "Says the July 15 rating cannot be used because it was not on record with the office responsible for retention registers until August 15, after the July 20 cutoff; cites 351.503(c)(2)-(3)."
    },
    "q4d_gina": {
      "verdict": "yes",
      "rationale": "Gina: August 15, 2022 is outside the period beginning September 3, 2022; 5 + 3 + proxy 4 = 12."
    },
    "q4e_modal": {
      "verdict": "yes",
      "rationale": "Says Hank's credit must be based on the modal rating for the applicable summary-level pattern under 351.503(f)(1); a specific number is offered only as an illustration."
    },
    "q4e_flag": {
      "verdict": "yes",
      "rationale": "Flags that the 5 CFR 351.203 definition of modal rating is not printed in the 2026 documents and that the actual modal rating is not supplied, so the 9-point illustration is an assumption."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "The answer cites 351.503 and the relevant FR pages."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "The description of the modal-rating discussion at 91 FR 49193 is supported by the text; no fabrication."
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "verdict": "yes",
      "rationale": "Says the earlier rules govern the August 28, 2026 notice because the notice was issued before September 2, 2026, even though the RIF takes effect October 27."
    },
    "q5a_i_result": {
      "verdict": "yes",
      "rationale": "Uses the final rule's description of the old credit (Level 3 = 12 years, Level 5 = 20 years) and gives Lee an adjusted SCD in 1986 and Park in 1999, so Park is released."
    },
    "q5a_ii": {
      "verdict": "yes",
      "rationale": "For September 2, 2026, says the amended rules apply because the notice was on or after the effective date; Lee 9, Park 21, Lee released."
    },
    "q5a_iii": {
      "verdict": "yes",
      "rationale": "For September 3, 2026, applies the amended rules and says Lee is released."
    },
    "q5b_no_recalc": {
      "verdict": "yes",
      "rationale": "Says no recalculation: under 5 CFR 351.805(b) an amended notice solely stating a later effective date is not a new specific RIF notice and does not require redetermination; standing was fixed on receipt of the September 3 notice."
    },
    "q5c_version": {
      "verdict": "yes",
      "rationale": "Version of the rules is fixed by the date the agency issues the RIF notice, before or on/after September 2, 2026."
    },
    "q5c_window": {
      "verdict": "yes",
      "rationale": "The four-year ratings period ends at issuance of the RIF notices or at the agency's cutoff date under 351.503(c)(1)-(2)."
    },
    "q5c_standing": {
      "verdict": "yes",
      "rationale": "Tenure subgroup and retention standing are fixed as of the date the employee receives the specific RIF notice, citing 351.502 and 351.507(a)."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "Citations are supplied throughout."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented source; the old-rule description is taken from the 2026 documents."
    }
  },
  "Q6": {
    "q6a_reach": {
      "verdict": "yes",
      "rationale": "Correctly reaches positions 1, 2, and 3 and rules out 4 (four grades down), 5 (higher-standing holder), 6 (part-time), and 7 (different competitive area)."
    },
    "q6a_offer": {
      "verdict": "yes",
      "rationale": "Says the agency must offer position 1, the GS-12 held by Ellis, as the least reduction in representative rate."
    },
    "q6b_five": {
      "verdict": "yes",
      "rationale": "Says the grade limit becomes five grades, making position 4 (GS-9) reachable, while the offer remains position 1."
    },
    "q6c_level1": {
      "verdict": "yes",
      "rationale": "Says a current Level 1 rating means no assignment right under 351.701."
    },
    "q6d_excepted": {
      "verdict": "yes",
      "rationale": "Says 351.701 does not give mandatory assignment rights in the excepted service; the agency may adopt them under 351.705(a)."
    },
    "q6e_level2": {
      "verdict": "yes",
      "rationale": "Says the former 351.701(d) restriction on Level 2 employees taking positions held by higher-rated employees was eliminated."
    },
    "q6e_bump": {
      "verdict": "yes",
      "rationale": "Says bumping and retreating were replaced by a single assignment right to a position held by an employee with lower retention standing."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "The answer cites 351.701, 351.705 and the preamble pages."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation."
    }
  },
  "Q7": {
    "q7a_mspb": {
      "verdict": "yes",
      "rationale": "Concludes the MSPB hears the appeal because the notice was issued August 31, 2026, before OPM's September 2, 2026 applicability date."
    },
    "q7a_board_rule": {
      "verdict": "yes",
      "rationale": "Cites FR Doc. 2026-16456, 91 FR 51997, and its statements that the Board will continue to accept and adjudicate RIF appeals where the agency's RIF notice was issued before the effective date."
    },
    "q7b_opm": {
      "verdict": "yes",
      "rationale": "Says the appeal goes to OPM under 5 CFR 351.901(a) and 2026-15666."
    },
    "q7b_count": {
      "verdict": "yes",
      "rationale": "Shows the count: day 1 December 19, 2026; day 30 Sunday, January 17, 2027."
    },
    "q7b_date": {
      "verdict": "yes",
      "rationale": "Gives the last day as Tuesday, January 19, 2027, because Monday, January 18, is a federal holiday."
    },
    "q7b_efile": {
      "verdict": "yes",
      "rationale": "Says filing is through OPM's electronic filing system and timely by 11:59 p.m. Eastern Time on the final day."
    },
    "q7c_burden": {
      "verdict": "yes",
      "rationale": "Places the burden on Morgan, by a preponderance, to show a statutory or regulatory violation and prejudice, along with timeliness and jurisdiction."
    },
    "q7c_hearing": {
      "verdict": "yes",
      "rationale": "Says no hearing as of right; review is on the written record unless OPM determines a hearing is necessary and efficient under 351.905(c)."
    },
    "q7d_text": {
      "verdict": "yes",
      "rationale": "Says 351.901(c)(2) bars raising the RIF action under a negotiated grievance procedure or through grievance arbitration."
    },
    "q7d_flag": {
      "verdict": "yes",
      "rationale": "Reports the preamble's position on existing agreements: no retroactive invalidation; bargaining limited on renegotiation; existing-agreement questions remain for chapter 71 resolution."
    },
    "q7e_court": {
      "verdict": "yes",
      "rationale": "Says no judicial review under 351.901(c)(4) and no further appeal from a final OPM decision under 351.909(e)."
    },
    "q7f_tolling": {
      "verdict": "yes",
      "rationale": "Says she may still appeal under 351.902(b)(3) and gives April 9, 2027, 30 days after the March 10, 2027 OSC decision."
    },
    "q7g_where": {
      "verdict": "yes",
      "rationale": "Locates the applicability rule in the DATES paragraph at 91 FR 49230 and the preamble, and does not attribute it to the regulatory text of 351.901."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "The answer cites the rule, CFR paragraphs, and FR pages throughout."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation."
    }
  },
  "Q8": {
    "q8a_adopted": {
      "verdict": "yes",
      "rationale": "Identifies 2026-21320 as revising 351.806, effective November 18, 2026, and says it is not yet in force on November 14, 2026."
    },
    "q8a_new_text": {
      "verdict": "yes",
      "rationale": "Gives the adopted text: ordinary circumstances duty status, and administrative leave for all or part of the notice period when appropriate and consistent with part 630, subpart N."
    },
    "q8a_today": {
      "verdict": "yes",
      "rationale": "Says the version applying today keeps the employee in duty status 'when possible', citing OPM's description in the proposed rule at 91 FR 39034, 39036."
    },
    "q8b_consent": {
      "verdict": "yes",
      "rationale": "Says consent is not required: 630.1403(c)(10) covers RIF-notice administrative leave at the agency's discretion, and the preamble says leave may be provided with or without consent."
    },
    "q8b_cap": {
      "verdict": "yes",
      "rationale": "The answer states the duration limits as the notice period and the period between receipt and separation, and says the 12-week limit is for 630.1403(c)(9) and (c)(11), not (c)(10); this conveys that no numeric cap is stated for (c)(10)."
    },
    "q8b_12wk": {
      "verdict": "yes",
      "rationale": "Explains that the 12-week workforce-realignment limit is stated for the uses in 630.1403(c)(9) and (c)(11), not the RIF-notice use in (c)(10)."
    },
    "q8b_flag": {
      "verdict": "yes",
      "rationale": "Its uncertainty section says whether the 12-week limit could apply by policy to (c)(10) is not established by the regulatory text, and it also notes the adopted rule is not yet in force."
    },
    "q8c_guidance": {
      "verdict": "yes",
      "rationale": "Points to OPM's Template for Agency Administrative Leave Policies, CPM 2025-12, July 30, 2025, and says it already allowed leave between receipt of an involuntary-separation notice and the effective date, citing 91 FR 65926."
    },
    "q8d_no_effect": {
      "verdict": "yes",
      "rationale": "Says no: the provisions address only paid non-duty status during the notice period and do not alter RIF competition, retention-register, notice, or appeal requirements, citing 91 FR 65926."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant FR pages and CFR provisions."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation."
    }
  },
  "Q9": {
    "q9_s1": {
      "verdict": "yes",
      "rationale": "Step 1 does not comply: August 17 to October 13 is less than 90 days, so 351.402(c) required submission of the competitive-area description and bona fide organizational statement to OPM for approval in advance."
    },
    "q9_s3": {
      "verdict": "yes",
      "rationale": "Step 3 does not comply: a career employee on supervisory probation is not serving an 'initial probationary period' under the 351.203 definition; she must be ranked. The answer cites the preamble at 91 FR 49191."
    },
    "q9_s4": {
      "verdict": "yes",
      "rationale": "Step 4 does not comply: the cutoff was September 13, 2026, so the October 2, 2026 rating could not be used, and the answer also notes the need for uniform treatment."
    },
    "q9_s5": {
      "verdict": "yes",
      "rationale": "Step 5 does not comply: with two ratings, the proxy is (7 + 5)/2 = 6, so Quist's credit is 7 + 5 + 6 = 18, not 15."
    },
    "q9_s6": {
      "verdict": "yes",
      "rationale": "Step 6 does not comply: under a single five-level pattern, 351.503(d) does not permit the 2-point QSI enhancement, and 351.503(e) applies only with multiple patterns."
    },
    "q9_s8": {
      "verdict": "yes",
      "rationale": "Step 8 does not comply: 351.602(a) bars releasing a competing employee while retaining one on a specifically limited temporary or term promotion."
    },
    "q9_s10": {
      "verdict": "yes",
      "rationale": "Step 10 does not comply: 351.702(a)(4)(iii) bars an assessment consisting solely of, or principally relying on, an automated self-assessment."
    },
    "q9_s11": {
      "verdict": "yes",
      "rationale": "Step 11 does not comply: 351.608(a)(3) prohibits sequencing or stacking temporary exceptions; the agency may use only the single longest exception."
    },
    "q9_s12": {
      "verdict": "yes",
      "rationale": "Step 12 does not comply: notices issued October 13, 2026 are governed by OPM appeal procedures under part 351, subpart I, not MSPB; the notice must advise appeal to OPM."
    },
    "q9_ok": {
      "verdict": "yes",
      "rationale": "Says steps 2, 7, and 9 are all in order and gives the deciding provisions for each: 351.202(d)(2)-(3), 351.601(c), and 351.702(a)(4)(v)."
    },
    "q9_false2": {
      "verdict": "no",
      "rationale": "The answer says step 2 is in order."
    },
    "q9_false7": {
      "verdict": "no",
      "rationale": "The answer says step 7 is in order."
    },
    "q9_false9": {
      "verdict": "no",
      "rationale": "The answer says step 9 is in order."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "Every step is tied to CFR provisions or FR pages."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation."
    }
  },
  "Q10": {
    "q10a_gap": {
      "verdict": "yes",
      "rationale": "Says paragraph (1) contained only its introductory text and had no (1)(i) or (1)(ii) because instruction 11 of 2026-15665 set out only the introductory text."
    },
    "q10b_doc": {
      "verdict": "yes",
      "rationale": "Identifies FR Doc. 2026-18800, 91 FR 58363, published and effective September 15, 2026, restoring paragraphs (1)(i) and (1)(ii)."
    },
    "q10b_reason": {
      "verdict": "yes",
      "rationale": "Explains good cause under 5 U.S.C. 553(b)(B) and (d)(3): no substantive change, restoring text in effect before September 2, 2026 that OPM had not proposed to remove."
    },
    "q10c_lower": {
      "verdict": "yes",
      "rationale": "Declining a lower-representative-rate position does not remove her from 'displaced' under paragraph (1)(i)."
    },
    "q10c_same": {
      "verdict": "yes",
      "rationale": "Declining a same-representative-rate, same-work-schedule position means she is not 'displaced' under paragraph (1)(i)."
    },
    "q10_cite": {
      "verdict": "no",
      "rationale": "The answer cites 2026-15665, 2026-18800, and the relevant FR pages."
    },
    "q10_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation."
    }
  },
  "Q11": {
    "q11_valid_10": {
      "verdict": "yes",
      "rationale": "Item-by-item count: 1 counts 1 (framing; actual heading wording not stated); 2 counts 3; 3 counts 1 (Schedule C/G 'appointments' to 'employee serving under', confirmed at 91 FR 49191); 4 counts 1; 5 counts 1; 6 counts 1; 7 counts 1; 8 counts 1; 9 counts 1; 10 counts 1; 11 counts 1; 12 counts 1; 13 counts 1; 14 counts 1; 15 counts 1; 16 not counted (final 351.503(b)(2) actually says 'Sec. 351.501', not 'paragraph (a)'); 17 counts 1 (the 91 FR 41521 addition; cross-reference already counted); 18 not counted (duplicate 430.208(d)-to-(e) cross-reference); 19 not counted (duplicate 91 FR 41521 addition); 20 counts 1; 21 counts 1; 22 counts 1; 23 counts 1; 24 counts 3; 25 counts 1; 26 counts 1; 27 counts 1; 28 counts 1; 29 counts 1; 30 counts 3; 31 counts 1. Total valid differences = 34."
    },
    "q11_valid_16": {
      "verdict": "yes",
      "rationale": "Same count as q11_valid_10: 34 valid differences."
    },
    "q11_valid_22": {
      "verdict": "yes",
      "rationale": "Same count: 34 valid differences."
    },
    "q11_valid_28": {
      "verdict": "yes",
      "rationale": "Same count: 34 valid differences."
    },
    "q11_valid_34": {
      "verdict": "yes",
      "rationale": "Same count: 34 valid differences, reaching the top rung."
    },
    "q11_deep": {
      "verdict": "yes",
      "rationale": "States well over six of the listed deeper differences, including 351.502 issue/receive, 351.701(a) 'minimally successful/satisfactory', 351.504 'should/must', 351.505(b)(2) cross-reference, 351.506(d), 351.702(a)(4)(v), 351.802(a)(2), 351.302(d), 351.608(a)(2), and the 91 FR 41521 addition."
    },
    "q11_cite": {
      "verdict": "no",
      "rationale": "The answer cites proposed and final FR pages and the correction."
    },
    "q11_fab": {
      "verdict": "no",
      "rationale": "Item 16 is a misreading of a real provision, not an invented source; no fabrication."
    }
  },
  "Q12": {
    "q12_quinn": {
      "verdict": "yes",
      "rationale": "Says Quinn is not a competing employee because she is serving the initial probationary period, so she is not ranked and may be retained."
    },
    "q12_ab": {
      "verdict": "yes",
      "rationale": "Alvarez: 7 + 7 + 5 = 19, no veterans' points. Brandt: 3 + 5 + 0 = 8, plus 5 = 13."
    },
    "q12_chen": {
      "verdict": "no",
      "rationale": "Gives Chen 12 (5 + 3 + proxy 4) instead of 18. The 2025 rating is Level 4 (5), not Level 3 (3); with only 7 and 5 in the period, the proxy is 6 and the total is 18."
    },
    "q12_dube": {
      "verdict": "no",
      "rationale": "Gives Dube 13, omitting the proxy for the missing third rating. Dube's two Level 4 ratings yield proxy 5 and performance credit 15, plus 3 = 18."
    },
    "q12_estrada": {
      "verdict": "yes",
      "rationale": "Estrada: 5 + 3 + 5 = 13, plus 3 = 16; the October 20, 2026 rating is excluded as post-notice."
    },
    "q12_farouk_score": {
      "verdict": "yes",
      "rationale": "Farouk: one rating, 3 x 3 = 9, no veterans' points, and last in the answer's order."
    },
